import{_ as o,C as a,o as i,c as l,j as e,a as s,E as r,a2 as u}from"./chunks/framework.TaNiW7i8.js";const q=JSON.parse('{"title":"Synchronisation","description":"","frontmatter":{"title":"Synchronisation"},"headers":[],"relativePath":"guide/sync.md","filePath":"guide/sync.md"}'),c={name:"guide/sync.md"};function d(m,n,g,h,p,f){const t=a("Capture");return i(),l("div",null,[n[0]||(n[0]=e("h1",{id:"synchronisation",tabindex:"-1"},[s("Synchronisation "),e("a",{class:"header-anchor",href:"#synchronisation","aria-label":'Permalink to "Synchronisation"'},"​")],-1)),n[1]||(n[1]=e("p",null,"Votre mémoire est un dépôt git ordinaire. Kessho la synchronise avec le git installé sur votre ordinateur, vers le distant que vous choisissez, et ne force jamais rien. Un témoin vous dit aussi quand la mémoire vient de changer.",-1)),r(t,{name:"synchro",alt:"La synchronisation de la mémoire : fichiers modifiés depuis le dernier commit et message de commit en cours de saisie."}),n[2]||(n[2]=u('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><p>La synchronisation se pilote à deux endroits : la barre d&#39;état, pour un clic, et <a href="/Kessho/guide/settings.html">Réglages</a> &gt; <strong>Synchronisation</strong>, pour le détail.</p><ul><li><strong>Dans la barre d&#39;état</strong>, en bas de la fenêtre : <ul><li>le bouton <strong>Synchroniser la mémoire</strong>, tout à gauche (infobulle : « Synchroniser : commiter, récupérer, pousser ») ;</li><li>le champ <strong>GIT</strong>, qui dit où en est le dépôt : <strong>à jour</strong>, <strong>N à pousser</strong>, <strong>N à récupérer</strong>, <strong>N non commités</strong>, <strong>conflit</strong> ou <strong>opération en cours</strong>. L&#39;infobulle donne la ligne d&#39;état complète.</li></ul></li><li><strong>Dans Réglages &gt; Synchronisation</strong> : <ul><li><strong>La ligne d&#39;état</strong> : la branche et son suivi, puis le retard et l&#39;avance, par exemple « main → origin/main · 2 à pousser · 0 à récupérer · distant consulté 10:30 ». L&#39;heure est celle de la dernière consultation du distant.</li><li><strong>Les trois gestes</strong> : <strong>Synchroniser</strong>, <strong>Récupérer</strong>, <strong>Pousser</strong>.</li><li><strong>Changements</strong> : le nombre de fichiers modifiés, supprimés et non suivis (« 3 modifiés · 0 supprimés · 1 non suivis »), la liste dépliable <strong>Voir la liste</strong>, le champ <strong>Message de commit</strong> et le bouton <strong>Commiter les changements</strong>.</li><li><strong>Distant</strong> : l&#39;adresse du dépôt distant, et le champ <strong>URL du distant (https ou ssh)</strong>.</li><li><strong>Automatisme</strong> : la case « Les agents commitent et synchronisent automatiquement ».</li><li><strong>Signalements</strong>, quand il y a quelque chose à dire.</li></ul></li><li><strong>Le témoin de fraîcheur</strong>, en haut à droite, à côté de votre avatar : une pastille qui s&#39;allume quand la mémoire change.</li></ul><p>Si la mémoire n&#39;est pas encore un dépôt, la section dit : « Cette mémoire n&#39;est pas un dépôt git. L&#39;initialiser ne crée aucun commit et ne la relie à aucun distant. » Si git n&#39;est pas installé, elle affiche « git introuvable » avec la commande pour l&#39;installer. Le reste de Kessho fonctionne sans git.</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="synchroniser-en-un-clic" tabindex="-1">Synchroniser en un clic <a class="header-anchor" href="#synchroniser-en-un-clic" aria-label="Permalink to &quot;Synchroniser en un clic&quot;">​</a></h3><p>Cliquez <strong>Synchroniser la mémoire</strong> dans la barre d&#39;état. Kessho fait trois choses, dans cet ordre :</p><ol><li>il commite ce qui a changé, sous le message « vault backup: AAAA-MM-JJ HH:mm:ss » (rien n&#39;est commité s&#39;il n&#39;y a rien de nouveau) ;</li><li>il récupère les nouveautés du distant ;</li><li>il pousse vos commits.</li></ol><p>Rien n&#39;est mis de côté et rien n&#39;est forcé. À la fin, le champ <strong>GIT</strong> se met à jour ; un lecteur d&#39;écran entend « Mémoire synchronisée. ».</p><p>Si quelque chose bloque, la barre affiche « échec : » suivi d&#39;un mot (<strong>conflit</strong>, <strong>hors ligne</strong>, <strong>authentification</strong>, <strong>arbre sale</strong>, <strong>occupé</strong>, <strong>délai</strong>, <strong>identité</strong>, <strong>marqueurs</strong>). Passez la souris dessus pour lire la raison complète. Si le commit de sauvegarde a eu lieu avant l&#39;échec, le message le précise : il est fait localement.</p><p>Le bouton est grisé, avec la raison en infobulle, quand aucun distant n&#39;est connecté (« Aucun distant : connectez-en un plus bas. ») ou qu&#39;une opération git est déjà en cours.</p><h3 id="commiter-vos-changements-a-la-main" tabindex="-1">Commiter vos changements à la main <a class="header-anchor" href="#commiter-vos-changements-a-la-main" aria-label="Permalink to &quot;Commiter vos changements à la main&quot;">​</a></h3><p>Dans <strong>Changements</strong> :</p><ol><li>Cliquez <strong>Voir la liste</strong> pour lire les fichiers concernés.</li><li>Écrivez un <strong>Message de commit</strong>.</li><li>Cliquez <strong>Commiter les changements</strong>, puis <strong>Confirmer</strong> à la question « Commiter N changements avec ce message ? ». <strong>Annuler</strong> abandonne.</li></ol><p>Le bouton reste grisé tant que le message est vide. Le message ne peut pas dépasser 1 000 caractères. Il faut que votre nom et votre courriel de commit soient renseignés dans votre profil (le rond avec votre initiale, en haut à droite).</p><h3 id="recuperer-ou-pousser" tabindex="-1">Récupérer ou pousser <a class="header-anchor" href="#recuperer-ou-pousser" aria-label="Permalink to &quot;Récupérer ou pousser&quot;">​</a></h3><ul><li><strong>Récupérer</strong> va chercher les nouveautés du distant et les applique. Il est grisé tant que des changements ne sont pas commités : « Des changements non commités empêchent la récupération : commitez-les d&#39;abord. »</li><li><strong>Pousser</strong> envoie vos commits. Il est grisé quand il n&#39;y a rien à pousser.</li><li><strong>Synchroniser</strong> récupère, puis pousse.</li></ul><p>Kessho ne récupère jamais tout seul : la ligne d&#39;état affiche « N à récupérer », et c&#39;est à vous de décider.</p><h3 id="connecter-un-distant" tabindex="-1">Connecter un distant <a class="header-anchor" href="#connecter-un-distant" aria-label="Permalink to &quot;Connecter un distant&quot;">​</a></h3><p>Dans <strong>Distant</strong>, collez l&#39;adresse du dépôt dans <strong>URL du distant (https ou ssh)</strong> et cliquez <strong>Connecter</strong> (le bouton devient <strong>Modifier</strong> quand un distant est déjà connecté). Les formes acceptées sont <code>https://hôte/chemin</code>, <code>ssh://hôte/chemin</code> et <code>utilisateur@hôte:chemin</code>.</p><p>Aucun identifiant n&#39;est stocké : Kessho utilise ceux de votre système. Une adresse qui en contient un est refusée.</p><h3 id="initialiser-le-depot" tabindex="-1">Initialiser le dépôt <a class="header-anchor" href="#initialiser-le-depot" aria-label="Permalink to &quot;Initialiser le dépôt&quot;">​</a></h3><p>Si votre mémoire n&#39;est pas encore un dépôt, cliquez <strong>Initialiser le dépôt</strong>. Cela ne crée aucun commit et ne la relie à aucun distant.</p><h3 id="laisser-vos-agents-synchroniser" tabindex="-1">Laisser vos agents synchroniser <a class="header-anchor" href="#laisser-vos-agents-synchroniser" aria-label="Permalink to &quot;Laisser vos agents synchroniser&quot;">​</a></h3><p>La case <strong>Automatisme</strong> (« Les agents commitent et synchronisent automatiquement ») est cochée par défaut. Quand elle l&#39;est, chaque outil de vos agents IA qui écrit dans la mémoire commite ce qu&#39;il a touché, et lui seul, puis pousse. Vos changements non commités ne partent jamais avec lui. Décochez la case pour reprendre la main.</p><p>Pour demander une synchronisation à un agent, voir <a href="/Kessho/agent/synchroniser.html">Synchroniser la mémoire</a>. Les outils correspondants sont décrits dans la <a href="/Kessho/reference/mcp/git.html">référence MCP</a>.</p><h3 id="comprendre-un-refus" tabindex="-1">Comprendre un refus <a class="header-anchor" href="#comprendre-un-refus" aria-label="Permalink to &quot;Comprendre un refus&quot;">​</a></h3><p>Les messages disent quoi faire. Les plus courants :</p><ul><li><strong>Conflit</strong> : la récupération est annulée et rien n&#39;a changé. Les fichiers en cause sont nommés : fusionnez-les à la main, commitez, puis synchronisez.</li><li><strong>Poussée refusée</strong> : le distant a avancé. Récupérez d&#39;abord. Rien n&#39;est jamais forcé.</li><li><strong>Hors ligne</strong> : le distant est injoignable. Rien n&#39;a changé, réessayez plus tard.</li><li><strong>Authentification refusée</strong> : Kessho emploie les identifiants de votre système. Pour GitHub en https, lancez « gh auth login » ; sinon passez le distant en SSH.</li><li><strong>Opération en cours</strong> ou <strong>dépôt occupé</strong> : un autre processus git travaille sur la mémoire. Attendez un instant.</li></ul><p>Dans <strong>Signalements</strong>, Kessho prévient aussi quand des marqueurs de conflit ont été commités dans un fichier, quand il a repris une opération interrompue, ou quand le greffon Obsidian Git synchronise la même mémoire (à deux, les automates se gênent : mettez ses intervalles à 0). Kessho ne modifie jamais la configuration d&#39;Obsidian.</p><h3 id="savoir-quand-la-memoire-a-change" tabindex="-1">Savoir quand la mémoire a changé <a class="header-anchor" href="#savoir-quand-la-memoire-a-change" aria-label="Permalink to &quot;Savoir quand la mémoire a changé&quot;">​</a></h3><p>Le témoin de fraîcheur, en haut à droite, s&#39;allume quand la mémoire change, par exemple quand un agent vient d&#39;écrire. Cliquez-le pour ouvrir son panneau.</p>',32)),r(t,{name:"fraicheur",alt:"Le témoin de fraîcheur, en haut à droite : un agent vient d'écrire dans la zone Procédures, le témoin s'allume et dit ce qui a bougé."}),n[3]||(n[3]=e("ul",null,[e("li",null,"La première ligne dit depuis quand : « Vu il y a une seconde. » Sans changement depuis l'ouverture : « Aucun changement depuis l'ouverture. » Si le relevé échoue : « Impossible de relever l'état de la mémoire. »"),e("li",null,[e("strong",null,"Mouvements depuis le dernier rechargement"),s(" liste les zones qui ont bougé, avec le nombre de mouvements : « Procédures 1 ». Ce nombre compte les mouvements, pas la taille de la zone : ajouter une note puis la retirer en fait deux.")]),e("li",null,"Quand une note a changé sans qu'aucune zone ne change de taille, le panneau le dit : « Une note a été modifiée, sans qu'aucune zone ne change de taille. »"),e("li",null,[e("strong",null,"Relire"),s(" recharge ce que l'écran affiche et remet le compteur à zéro.")])],-1))])}const b=o(c,[["render",d]]);export{q as __pageData,b as default};
